var SESSION_FRESH_MS = 15 * 60 * 1e3;
async function getSession(env, userId) {
  const raw = await env.COUPONS.get(`sess:${userId}`);
  if (!raw)
    return null;
  let sess;
  try {
    sess = JSON.parse(raw);
  } catch (e) {
    return null;
  }
  if (!sess.ts || Date.now() - sess.ts > SESSION_FRESH_MS) {
    await clearSession(env, userId);
    return null;
  }
  return sess;
}
